import React, { useState, ReactElement } from "react";
import FullscreenOverlay from "./FullscreenOverlay"; // Adjust the import path as needed

type FSImageProps = {
  children: ReactElement;
};

const FSImage: React.FC<FSImageProps> = ({ children }) => {
  const [isFullscreen, setIsFullscreen] = useState(false);

  const handleImageClick = (event: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
    setIsFullscreen(true);
    event.preventDefault();
    event.stopPropagation();
  };

  const handleClose = () => {
    setIsFullscreen(false);
  };

  // Stops propagation of click events to children
  const handleChildClick = (event: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
    setIsFullscreen(false);
  };

  return (
    <>
      <div onClick={handleImageClick} style={{ cursor: "pointer" }}>
        {children}
      </div>

      {isFullscreen && (
        <FullscreenOverlay isOpen={isFullscreen} onClose={handleClose}>
          <div onClick={handleChildClick} style={{  }}>
            {children}
          </div>
        </FullscreenOverlay>
      )}
    </>
  );
};

export default FSImage;
